// Expected callback declarations retain official typedef names.
// Each actual Rust alias carrier is independently checked below; no C++
// pointer, qualifier, argument, return, or calling convention is erased.

// Alias carriers are independently compared with the actual Rust alias.
// Native C++ enum signedness may differ from the C parser while retaining
// its value domain and ABI extent; no scalar/float/pointer substitution is allowed.
template<class T> constexpr const char *carrier_kind() {
    if constexpr (std::is_enum_v<T>) return "enum";
    else if constexpr (std::is_pointer_v<T>) return "pointer";
    else if constexpr (std::is_floating_point_v<T>) return "float";
    else if constexpr (std::is_integral_v<T>) return std::is_signed_v<T> ? "signed" : "unsigned";
    else return "record";
}

